with open("arrow/arrow.py", "r") as f:
    lines = f.readlines()

# Check for parser.TzinfoParser.parse in to() method
for i, line in enumerate(lines):
    if "parser.TzinfoParser.parse" in line and "tz)" in line:
        start = max(0, i-3)
        end = min(len(lines), i+3)
        for j in range(start, end):
            marker = ">>>" if j == i else "   "
            print(f"{marker} {j+1}: {lines[j]}", end='')
